    def __init__(self, accounts, api_key, api_secret, sleep_time):
        self.accounts = accounts
        self.api_key = api_key
        self.api_secret = api_secret
        self.sleep_time = sleep_time
        self.data = defaultdict(lambda: defaultdict(list))

    def get_oauth_token(self, api_key, api_secret):
        url = "https://api.twitter.com/1.1/oauth2/token"
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
        data = {"grant_type": "client_credentials"}
        response = requests.post(url, headers=headers, data=data)
        if response.status_code!= 200:
            print("Failed to get OAuth token")
            sys.exit(1)
        token_response_json = response.json()
        access_token = token_response_json["access_token"]
        return access_token

    def get_account_activity(self, account, access_token):
        url = f"https://api.twitter.com/1.1/statuses/user_timeline.json?screen_name={account}&count=200"
        headers = {"Authorization": f"Bearer {access_token}"}
        response = requests.get(url, headers=headers)
        if response.status_code!= 200:
            print(f"Failed to get activity for @{account}")
            return []
        activity_response_json = response.json()
        tweets = activity_response_json["statuses"]
        return tweets

    def track_accounts(self):
        access_token = self.get_oauth_token(self.api_key, self.api_secret)
        for account in self.accounts:
            tweets = self.get_account_activity(account, access_token)
            self.data[account].extend([(tweet["created_at"], tweet["text"]) for tweet in tweets])
            time.sleep(self.sleep_time)

    def save_data(self, filename):
        with open(filename, "w") as f:
            json.dump(self.data, f)

    def load_data(self, filename):
        try:
            with open(filename, "r") as f:
                self.data = json.load(f)
        except FileNotFoundError:
            pass

